import { createAsyncThunk, createSlice } from "@reduxjs/toolkit";
import axios from "axios";

const initialState = {
  user: {},
  isLoading: false,
  isSuccess: false,
  isError: false,
};

// ✅ Thunk للتسجيل — الاسم حسب طلبك
export const studentregister = createAsyncThunk(
  "users/studentregister",
  async (userData, thunkAPI) => {
    try {
      const response = await axios.post(
        "http://localhost:3001/registerUser",
        userData
      );
      return response.data;
    } catch (error) {
      return thunkAPI.rejectWithValue("Registration failed");
    }
  }
);

// ✅ Thunk لتسجيل الدخول
export const userlogin = createAsyncThunk(
  "users/userlogin",
  async (loginData, thunkAPI) => {
    try {
      const response = await axios.post(
        "http://localhost:3001/login",
        loginData
      );
      localStorage.setItem("userData", JSON.stringify(response.data.user));
      return response.data.user;
    } catch (error) {
      return thunkAPI.rejectWithValue("Wrong email or password");
    }
  }
);

const userSlice = createSlice({
  name: "users",
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder

      // ✅ studentregister
      .addCase(studentregister.pending, (state) => {
        state.isLoading = true;
        state.isError = false;
        state.isSuccess = false;
      })
      .addCase(studentregister.fulfilled, (state) => {
        state.isLoading = false;
        state.isSuccess = true;
      })
      .addCase(studentregister.rejected, (state) => {
        state.isLoading = false;
        state.isError = true;
      })

      // ✅ userlogin
      .addCase(userlogin.pending, (state) => {
        state.isLoading = true;
        state.isError = false;
      })
      .addCase(userlogin.fulfilled, (state, action) => {
        state.isLoading = false;
        state.user = action.payload;
        state.isSuccess = true;
      })
      .addCase(userlogin.rejected, (state) => {
        state.isLoading = false;
        state.isError = true;
      });
  },
});

export default userSlice.reducer;
